import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import { pathToFileURL } from 'node:url';
import { build } from 'esbuild';
import { JSDOM } from 'jsdom';
import React, { act } from 'react';

// Every document and IPC response below is generated by this test.
const dom = new JSDOM('<!doctype html><div id="root"></div>', { url: 'http://localhost' });
for (const key of ['window', 'document', 'navigator', 'localStorage', 'HTMLElement', 'MutationObserver']) {
  Object.defineProperty(globalThis, key, { value: dom.window[key], configurable: true });
}
window.matchMedia = () => ({ matches: false });
globalThis.IS_REACT_ACT_ENVIRONMENT = true;
const { createRoot } = await import('react-dom/client');
const listeners = new Map();
globalThis.nativeDropListen = async (event, callback) => {
  listeners.set(event, callback);
  return () => { if (listeners.get(event) === callback) listeners.delete(event); };
};
const output = path.resolve('node_modules/.cache/deditor-native-file-drop.mjs');
fs.mkdirSync(path.dirname(output), { recursive: true });
globalThis.nativeDropInvoke = async () => undefined;
globalThis.nativeDropErrors = [];
const stubs = {
  '@tauri-apps/api/core': 'export const invoke=(...a)=>globalThis.nativeDropInvoke(...a); export const convertFileSrc=p=>p;',
  '@tauri-apps/api/event': 'export const listen=(...a)=>globalThis.nativeDropListen(...a);',
  '@tauri-apps/plugin-dialog': 'export const open=async()=>null; export const save=async()=>null;',
  '@tauri-apps/plugin-opener': 'export const revealItemInDir=async()=>{}; export const openUrl=async()=>{}; export const openPath=async()=>{};',
  components: 'export default ()=>null; export const confirmUnsaved=async()=>"cancel";',
  fileWatch: 'export const useFileWatch=()=>{};',
  idlePrefetch: 'export const scheduleIdlePrefetch=()=>()=>{};',
};
await build({
  stdin: { contents: `
export {createNativeFileDropHandler} from './src/lib/nativeFileDrop';
export {loadPersisted} from './src/lib/persistence';
export {openMany,setWorkspaceByPath} from './src/lib/fileio';
export {useEditorStore} from './src/store/editor';
export {handleWindowsFileShortcut} from './src/lib/windowsFileShortcuts';
export {default as App} from './src/App';
`, resolveDir: process.cwd() },
  outfile: output, bundle: true, format: 'esm', jsx: 'automatic', platform: 'node', packages: 'external',
  loader: { '.css': 'empty' }, logLevel: 'silent',
  plugins: [{ name: 'generated-io', setup(b) {
    b.onResolve({ filter: /.*/ }, a => stubs[a.path]
      ? { path: a.path, namespace: 'stub' }
      : a.path.includes('/components/') ? { path: 'components', namespace: 'stub' }
      : a.path.endsWith('/fileWatch') ? { path: 'fileWatch', namespace: 'stub' }
      : a.path.endsWith('/idlePrefetch') ? { path: 'idlePrefetch', namespace: 'stub' }
      : a.path.endsWith('/feedback') ? { path: 'feedback', namespace: 'stub' } : undefined);
    b.onLoad({ filter: /.*/, namespace: 'stub' }, a => ({
      contents: a.path === 'feedback' ? 'export const showError=async text=>{globalThis.nativeDropErrors.push(text);};' : stubs[a.path], loader: 'js',
    }));
  } }],
});
const app = await import(pathToFileURL(output));
const deferred = () => {
  let resolve;
  const promise = new Promise(r => { resolve = r; });
  return { promise, resolve };
};
const actual = (isClosing = () => false) => app.createNativeFileDropHandler({
  isClosing,
  pathKind: path => globalThis.nativeDropInvoke('path_kind', { path }),
  addWorkspace: app.setWorkspaceByPath,
  openFiles: app.openMany,
});
let passed = 0;
async function test(name, run) {
  await run(); passed++; console.log('PASS ' + name);
}

await test('1 startup recovery completes before a queued Windows drop opens', async () => {
  const state = deferred(), commands = [];
  globalThis.nativeDropInvoke = async (command, args) => {
    commands.push(command);
    if (command === 'read_app_state') return state.promise;
    if (command === 'path_kind') return 'file';
    if (command === 'read_text_file') return 'generated dropped contents';
  };
  const drop = actual();
  const restore = app.loadPersisted();
  const pending = drop.handle(['C:\\generated\\中文 drop.md']);
  await Promise.resolve();
  assert.deepEqual(commands, ['read_app_state']);
  state.resolve(JSON.stringify({ v: 3, tabs: [{ filePath: null, recoveryId: 'generated-recovery', content: 'generated recovery', savedContent: '' }], workspaces: [], activeIndex: 0 }));
  await restore;
  drop.ready(); await pending;
  const tabs = app.useEditorStore.getState().tabs;
  assert.ok(tabs.some(tab => tab.content === 'generated recovery'));
  assert.ok(tabs.some(tab => tab.filePath === 'C:\\generated\\中文 drop.md' && tab.content === 'generated dropped contents'));
  drop.dispose();

  // Mount the real App as well, to verify its subscription/ready/cleanup wiring.
  // Child rendering is isolated; recovery, the store and file opening are real.
  const appState = deferred();
  globalThis.nativeDropInvoke = async command => command === 'read_app_state' ? appState.promise
    : command === 'path_kind' ? 'file' : command === 'read_text_file' ? 'generated App drop' : undefined;
  const root = createRoot(document.getElementById('root'));
  await act(async () => { root.render(React.createElement(app.App)); });
  const subscribedDrop = listeners.get('tauri://drag-drop');
  assert.ok(subscribedDrop);
  const appPending = subscribedDrop({ payload: { paths: ['C:\\generated\\app.md'] } });
  assert.ok(!app.useEditorStore.getState().tabs.some(tab => tab.filePath === 'C:\\generated\\app.md'));
  await act(async () => {
    appState.resolve(JSON.stringify({ v: 3, tabs: [{ filePath: null, recoveryId: 'app-recovery', content: 'generated App recovery', savedContent: '' }], workspaces: [], activeIndex: 0 }));
    await appPending;
  });
  assert.ok(app.useEditorStore.getState().tabs.some(tab => tab.content === 'generated App recovery'));
  assert.ok(app.useEditorStore.getState().tabs.some(tab => tab.filePath === 'C:\\generated\\app.md' && tab.content === 'generated App drop'));
  await act(async () => root.unmount());
  assert.ok(!listeners.has('tauri://drag-drop'));
});

await test('2 ready mixed drops preserve file ordering and folder dispatch', async () => {
  const calls = [];
  const drop = app.createNativeFileDropHandler({
    isClosing: () => false,
    pathKind: async path => { calls.push(['probe', path]); return path.endsWith('folder') ? 'dir' : 'file'; },
    addWorkspace: async path => { calls.push(['folder', path]); },
    openFiles: async paths => { calls.push(['files', paths]); },
  });
  drop.ready();
  await drop.handle(['C:\\generated\\b.md', 'C:\\generated\\folder', '\\\\generated-server\\share\\a.md']);
  assert.deepEqual(calls, [
    ['probe', 'C:\\generated\\b.md'], ['probe', 'C:\\generated\\folder'], ['folder', 'C:\\generated\\folder'],
    ['probe', '\\\\generated-server\\share\\a.md'], ['files', ['C:\\generated\\b.md', '\\\\generated-server\\share\\a.md']],
  ]);
  calls.length = 0; await drop.handle([]); assert.deepEqual(calls, []); drop.dispose();
});

await test('3 recovery rejection, failed probes/opens and folders keep the remaining files', async () => {
  globalThis.nativeDropErrors.length = 0;
  app.useEditorStore.getState().replaceTabs([], '');
  const reads = [];
  globalThis.nativeDropInvoke = async (command, args) => {
    if (command === 'read_app_state') throw new Error('generated recovery read failure');
    if (command === 'path_kind') {
      if (args.path.endsWith('bad.md')) throw new Error('generated probe failure');
      return args.path.endsWith('folder') ? 'dir' : 'file';
    }
    if (command === 'resolve_path') throw new Error('generated workspace failure');
    if (command === 'read_text_file') {
      reads.push(args.path);
      if (args.path.endsWith('bad.md')) throw new Error('generated open failure');
      return 'generated valid contents';
    }
  };
  const drop = actual();
  const pending = drop.handle(['C:\\generated\\folder', 'C:\\generated\\bad.md', 'C:\\generated\\good.md']);
  try { await app.loadPersisted(); } finally { drop.ready(); }
  await pending;
  assert.deepEqual(reads, ['C:\\generated\\bad.md', 'C:\\generated\\good.md']);
  assert.equal(globalThis.nativeDropErrors.length, 1);
  assert.equal(app.useEditorStore.getState().tabs.find(tab => tab.filePath?.endsWith('good.md'))?.content, 'generated valid contents');
  drop.dispose();
});

await test('4 unmount and committed close release startup waits and stop pending probes', async () => {
  for (const phase of ['startup-dispose', 'startup-close', 'probe-dispose', 'probe-close']) {
    const probe = deferred(), calls = [];
    let closing = false;
    const drop = app.createNativeFileDropHandler({
      isClosing: () => closing,
      pathKind: async path => { calls.push(path); return probe.promise; },
      addWorkspace: async () => assert.fail('stopped drop opened a workspace'),
      openFiles: async () => assert.fail('stopped drop opened files'),
    });
    if (phase.startsWith('probe')) drop.ready();
    const pending = drop.handle(['C:\\generated\\a.md', 'C:\\generated\\b.md']);
    if (phase.endsWith('dispose')) drop.dispose(); else closing = true;
    drop.ready(); probe.resolve('file'); await pending;
    assert.equal(calls.length, phase.startsWith('probe') ? 1 : 0, phase);
    drop.dispose();
  }
  const folder = deferred(), folderEntered = deferred(), probed = [];
  const drop = app.createNativeFileDropHandler({
    isClosing: () => false,
    pathKind: async path => { probed.push(path); return 'dir'; },
    addWorkspace: async () => { folderEntered.resolve(); await folder.promise; },
    openFiles: async () => assert.fail('disposed folder drop opened files'),
  });
  drop.ready();
  const pending = drop.handle(['C:\\generated\\folder', 'C:\\generated\\later-folder']);
  await folderEntered.promise;
  drop.dispose(); folder.resolve(); await pending;
  assert.deepEqual(probed, ['C:\\generated\\folder']);
});

await test('5 independent target windows and Windows file shortcuts retain one owner', async () => {
  const seen = { a: [], b: [] };
  const windowDrop = target => app.createNativeFileDropHandler({
    isClosing: () => false, pathKind: async () => 'file', addWorkspace: async () => {},
    openFiles: async paths => { seen[target].push(...paths); },
  });
  const a = windowDrop('a'), b = windowDrop('b');
  const pendingA = a.handle(['C:\\generated\\a.md']);
  const pendingB = b.handle(['C:\\generated\\b.md']);
  b.ready(); await pendingB; assert.deepEqual(seen, { a: [], b: ['C:\\generated\\b.md'] });
  a.ready(); await pendingA; assert.deepEqual(seen.a, ['C:\\generated\\a.md']);
  a.dispose(); b.dispose();
  for (const [key, shiftKey, expected] of [['n', false, 'file_new'], ['n', true, 'file_new_window'], ['o', false, 'file_open'], ['o', true, 'file_open_folder'], ['s', false, 'file_save'], ['s', true, 'file_save_as'], ['w', false, 'file_close_tab']]) {
    const actions = [], event = new window.KeyboardEvent('keydown', { key, ctrlKey: true, shiftKey, cancelable: true });
    assert.equal(app.handleWindowsFileShortcut(event, {}, action => actions.push(action), true), true);
    assert.equal(event.defaultPrevented, true); assert.deepEqual(actions, [expected]);
    assert.equal(app.handleWindowsFileShortcut(event, {}, action => actions.push(action), true), false);
    assert.deepEqual(actions, [expected]);
    const disabled = new window.KeyboardEvent('keydown', { key, ctrlKey: true, shiftKey, cancelable: true });
    assert.equal(app.handleWindowsFileShortcut(disabled, { [expected]: false }, () => assert.fail('disabled action ran'), true), false);
  }
  for (const options of [{ isComposing: true }, { altKey: true }, { metaKey: true }]) {
    assert.equal(app.handleWindowsFileShortcut(new window.KeyboardEvent('keydown', { key: 's', ctrlKey: true, ...options }), {}, () => assert.fail('invalid chord ran'), true), false);
  }
});

console.log(`${passed} native file-drop/Windows dispatch regression rounds passed (generated IPC, not native gesture acceptance)`);
dom.window.close();
